/// Hold the content one tab names, and show it when that tab is chosen.
///
/// # Accessibility
///
/// It claims no role until the script gives it one, and it carries
/// `aria-labelledby` pointing at its tab from the first render. Every panel is
/// visible with no script, so nothing is hidden behind a control that cannot work.
#[component]
pub fn TabPanel(
    /// The `Tabs` this belongs to. **Required**, and it must match the strip's own
    /// `name`. This panel's id and the tab that names it both derive from it, so a
    /// different word leaves the panel unreachable.
    name: String,
    /// Which tab shows this, matching the `Tab` of the same `value`. **Required**, and unique within one set, because it is half of both ids.
    value: String,
    /// Extra classes for the root element.
    #[props(default)]
    class: String,
    /// The content.
    children: Element,
) -> Element {
    let root = format!("nd-tab-panel {class}");
    let root = root.trim().to_owned();
    // The same two words the tab derived its own ids from.
    let id = format!("nd-tabs-{name}-{value}-panel");
    let tab = format!("nd-tabs-{name}-{value}");

    rsx! {
        div {
            class: "{root}",
            id: "{id}",
            // NO `role="tabpanel"` AND NO `hidden`. With no script every panel
            // is on the page, which is what makes the strip above it a table of
            // contents rather than a row of controls that do nothing.
            "aria-labelledby": "{tab}",
            "data-nd-value": "{value}",
            {children}
        }
    }
}
